use darling::{FromDeriveInput, FromVariant, ast::Fields};
use proc_macro2::{Span, TokenStream};
use quote::{format_ident, quote};
use syn::Ident;

/// Name of the module generated by the [`CanDecode`] macro which contains the
/// CAN decode implementation of the message enum
pub const CAN_DECODE_MESSAGE_META_TYPES_IDENT: &str = "__message_meta_can_decode";

// The [`darling::FromVariant`] macro seems to have needless continues
#[allow(clippy::needless_continue)]
#[derive(FromVariant)]
pub struct CanDecodeVariant {
    ident: Ident,
    fields: Fields<syn::Field>,
}

#[derive(FromDeriveInput)]
#[darling(attributes(can), supports(enum_any))]
pub struct CanDecode {
    #[darling(default)]
    /// Boolean whether the enum should be sparsely decodable
    pub sparse: bool,
    #[darling(default)]
    /// Boolean whether all enum variants need to be newtypes and have
    /// [`can_hal::Decode`] implemented
    pub dispatch: bool,

    pub ident: Ident,
    pub data: darling::ast::Data<CanDecodeVariant, ()>,
}

pub fn handle(can_decode: CanDecode) -> TokenStream {
    let variants = can_decode.data.take_enum().unwrap_or_default();
    let ident = can_decode.ident;

    let meta_can_decode_mod = Ident::new(CAN_DECODE_MESSAGE_META_TYPES_IDENT, Span::call_site());

    let decode_impl = if can_decode.dispatch {
        generate_can_decode_dispatch_impl(&ident, &variants)
            .unwrap_or_else(syn::Error::into_compile_error)
    } else {
        quote! {
            unimplemented!("todo: implement non-dispatch case")
        }
    };

    quote! {
        pub mod #meta_can_decode_mod {
            use super::#ident;

            #decode_impl
        }
    }
}

fn generate_can_decode_dispatch_impl(
    ident: &Ident,
    variants: &[CanDecodeVariant],
) -> syn::Result<TokenStream> {
    let (idents, types) = variants
        .iter()
        .map(|variant| {
            if !variant.fields.is_newtype() {
                return Err(syn::Error::new(
                    variant.ident.span(),
                    "All variants need to be newtypes when using `#[can(dispatch)]`",
                ));
            }

            let types = variant
                .fields
                .iter()
                .map(|field| &field.ty)
                .collect::<Vec<_>>();

            let variant_type = types.first().ok_or(syn::Error::new(
                variant.ident.span(),
                "Newtype enum variant should at least have one type",
            ))?;

            Ok((&variant.ident, *variant_type))
        })
        .collect::<syn::Result<(Vec<_>, Vec<_>)>>()?;

    let (error_ident, decode_error) = generate_can_decode_error(ident, variants)?;

    let output = quote! {
        #decode_error

        impl can_hal::CanDecode for #ident {
            type Error = #error_ident;

            fn from_parts(id: can_hal::StandardId, data: &[u8]) -> Result<Self, Self::Error> {
                #(
                    if #types::ALL_CAN_IDS.contains(&id) {
                        return #types::from_parts(id, data)
                            .map(Self::#idents)
                            .map_err(#error_ident::#idents);
                    }
                )*

                Err(#error_ident::Unknown(id))
            }
        }
    };
    Ok(output)
}

fn generate_can_decode_error(
    ident: &Ident,
    variants: &[CanDecodeVariant],
) -> syn::Result<(Ident, TokenStream)> {
    let error_ident = format_ident!("{ident}CanDecodeError");

    let (idents, mappings) = variants
        .iter()
        .map(|variant| {
            if !variant.fields.is_newtype() {
                return Err(syn::Error::new(
                    variant.ident.span(),
                    "All variants need to be newtypes when using `#[can(dispatch)]`",
                ));
            }

            let types = variant
                .fields
                .iter()
                .map(|field| &field.ty)
                .collect::<Vec<_>>();

            let variant_type = types.first().ok_or(syn::Error::new(
                variant.ident.span(),
                "Newtype enum variant should at least have one type",
            ))?;

            let mapping = quote! { <#variant_type as can_hal::CanDecode>::Error };

            Ok((&variant.ident, mapping))
        })
        .collect::<syn::Result<(Vec<_>, Vec<_>)>>()?;

    let output = quote! {
        #[derive(Debug, thiserror::Error)]
        pub enum #error_ident {
            #(
                #[error(transparent)] #idents(#mappings),
            )*
            #[error("Unknown CAN message with id {0:#x?}")]
            Unknown(can_hal::StandardId)
        }
    };

    Ok((error_ident, output))
}
